require_once '../config.php';requireAdmin();$id=(int)($_GET['id']??0);$p=['name'=>'','description'=>'','price'=>'','stock'=>0,'image'=>'','category_id'=>''];if($id){$s=$pdo->prepare("SELECT * FROM products WHERE id=?");$s->execute([$id]);$p=$s->fetch()?:$p;}
$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$data=[trim($_POST['name']??''), (int)($_POST['category_id']??0),trim($_POST['description']??''),(float)($_POST['price']??0),(int)($_POST['stock']??0),trim($_POST['image']??'')];
if(!$data[0]||$data[1]<1||$data[3]<0||$data[4]<0)$error='Confira os campos obrigatórios.';else{if($id){$s=$pdo->prepare("UPDATE products SET name=?,category_id=?,description=?,price=?,stock=?,image=? WHERE id=?");$s->execute([...$data,$id]);}else{$s=$pdo->prepare("INSERT INTO products(name,category_id,description,price,stock,image) VALUES(?,?,?,?,?,?)");$s->execute($data);}redirect('products.php');}}
