<div class="page-head"><div class="container"><div class="section-kicker">GESTÃO DO CATÁLOGO</div><h1><?= $id?'EDITAR PRODUTO':'CADASTRAR PRODUTO' ?></h1></div></div><section class="section"><div class="container"><div class="dark-panel mx-auto" style="max-width:760px"><?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?= e(csrfToken()) ?>"><label class="form-label">Nome do produto</label><input class="form-control mb-3" name="name" value="<?= e($p['name']) ?>" required><label class="form-label">Categoria</label><select class="form-select mb-3" name="category_id" required><?php foreach($cats as $c): ?><option value="<?= $c['id'] ?>" <?= $p['category_id']==$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select><label class="form-label">Descrição</label><textarea class="form-control mb-3" rows="4" name="description" required><?= e($p['description']) ?></textarea><div class="row"><div class="col-md-6"><label class="form-label">Preço (R$)</label><input class="form-control mb-3" type="number" step=".01" min="0" name="price" value="<?= e((string)$p['price']) ?>" required></div><div class="col-md-6"><label class="form-label">Estoque</label><input class="form-control mb-3" type="number" min="0" name="stock" value="<?= (int)$p['stock'] ?>" required></div></div><label class="form-label">URL da imagem</label><input class="form-control mb-4" name="image" value="<?= e($p['image']) ?>"><button class="btn-red">SALVAR PRODUTO</button> <a class="btn-outline" href="products.php">CANCELAR</a></form></div></div></section><?php include '../includes/footer.php'; ?>
